package main

import "fmt"

type Notifier interface {
	Send(msg string)
	Name() string
}

type base struct{}

func (base) Send(msg string) { fmt.Println("base:", msg) }
func (base) Name() string    { return "base" }

// SMSNotifier embeds the Notifier interface: Name() is delegated to the
// stored value, while our own Send shadows the promoted one.
type SMSNotifier struct {
	Notifier // embedded interface: promotes Send and Name to SMSNotifier
}

func (SMSNotifier) Send(msg string) { fmt.Println("sms:", msg) } // overrides Send

func main() {
	var n Notifier = SMSNotifier{Notifier: base{}} // store a base to delegate Name to
	n.Send("hello")          // our Send (shadows promoted)
	fmt.Println(n.Name())    // promoted from the embedded base
}

