package solution

import "sync"

type SafeMap struct {
	sync.Mutex // embedded: promotes Lock() and Unlock() onto SafeMap
	counts map[string]int
}

func NewSafeMap() *SafeMap {
	return &SafeMap{counts: make(map[string]int)}
}

func (m *SafeMap) Inc(key string) {
	m.Lock()         // promoted from sync.Mutex
	defer m.Unlock() // promoted from sync.Mutex
	m.counts[key]++
}

func (m *SafeMap) Get(key string) int {
	m.Lock()
	defer m.Unlock()
	return m.counts[key]
}

func Solve(keys []string) map[string]int {
	m := NewSafeMap()
	for _, k := range keys {
		m.Inc(k)
	}
	// Return a plain copy of the final counts for the caller.
	out := make(map[string]int, len(m.counts))
	m.Lock()
	for k, v := range m.counts {
		out[k] = v
	}
	m.Unlock()
	return out
}

