func TestSolve(t *testing.T) {
	cases := []struct {
		in   []string
		want map[string]int
	}{
		{[]string{"a", "b", "a"}, map[string]int{"a": 2, "b": 1}},
		{[]string{}, map[string]int{}},
		{[]string{"x", "x", "x"}, map[string]int{"x": 3}},
	}
	for _, c := range cases {
		if got := Solve(c.in); !reflect.DeepEqual(got, c.want) {
			t.Errorf("Solve(%v)=%v want %v", c.in, got, c.want)
		}
	}
}

