type Describer interface{ Describe() string }

type Employee struct{ Name string }

func (e Employee) Describe() string { return "an employee" }

// Introduce now takes the Describer explicitly — no reliance on dispatch.
func (e Employee) Introduce(d Describer) string {
	return e.Name + " is " + d.Describe()
}

type Manager struct {
	Employee // embedded for Name + Introduce
}

func (m Manager) Describe() string { return "a manager" }

func main() {
	m := Manager{Employee{Name: "Ada"}}
	// Pass m so the dynamic type's Describe is used.
	fmt.Println(m.Introduce(m)) // "Ada is a manager"
}

import "io"

type CountingWriter struct {
	io.Writer // embedded: promotes Write, so CountingWriter is an io.Writer
	n int64    // total bytes written
}

// Write shadows the promoted Write: count, then delegate to the wrapped writer.
func (cw *CountingWriter) Write(p []byte) (int, error) {
	written, err := cw.Writer.Write(p) // call the embedded value explicitly
	cw.n += int64(written)
	return written, err
}

func (cw *CountingWriter) Total() int64 { return cw.n }

import "sync"

type SafeCounter struct {
	sync.Mutex // embedded: promotes Lock() and Unlock() onto SafeCounter
	n int       // unexported count, guarded by the promoted mutex
}

// Inc increments the counter under the promoted lock.
func (c *SafeCounter) Inc() {
	c.Lock()         // promoted from sync.Mutex
	defer c.Unlock() // promoted from sync.Mutex
	c.n++
}

// Value reads the counter under the lock so it never races with Inc.
func (c *SafeCounter) Value() int {
	c.Lock()
	defer c.Unlock()
	return c.n
}
